/**
 * Wire-shape mirrors for every verb on antman's aspect endpoints —
 * request bodies, read responses, pull responses, compose/update
 * responses. One file covers the entire aspect surface so consumers
 * can `import { ... } from "./aspect.js"` without juggling
 * per-endpoint files.
 *
 * Mirrors of ultron's:
 *   - `AgentAspectInput` / `AgentAspectUpdateInput` / `AgentCategoryInput`
 *     (`ultron/.../aspect/agent/model/`)
 *   - `CloudMappingInput`, `CloudOptionsInput`, `RecordCreateTypesInput`,
 *     `ServiceConfigInput` (`ultron/.../aspect/definition/model/`)
 *   - `AgentAspectResponse` / `AgentAspectUpdateResponse` (compose +
 *     update response shapes)
 *
 * Antman declares the compose/update bodies as `Map<String, Object>`
 * to stay tolerant to ultron schema drift, but the EDK side is fully
 * typed via `AgentAspectInput` / `AgentAspectUpdateInput`. Antman
 * forwards the body verbatim and returns ultron's response with
 * `aspectId` + `aspectName`, which is what the late-binding registry
 * needs; the entity-client normalizes that to `id` on the way out
 * — see `aspects/index.ts`.
 *
 * Cross-entity imports are `import type` on purpose — `Aspect`
 * references `Agent` and `Agent` references `Aspect`, which is a
 * type-level cycle. `import type` is erased at compile time so no
 * runtime import is emitted and the cycle never materializes in JS.
 * Keep these imports type-only; promoting them to value imports will
 * reintroduce the runtime cycle and can break module initialization.
 *
 * Picklist values are canonical on `picklistValues` across all
 * endpoints — the entity-client normalizes antman's wire-side `values`
 * from the read endpoints to that name. See
 * `aspects/index.ts:normalizeFieldNames`.
 *
 * Symmetry note: shapes that read identically as compose-side input
 * and as pull-side response collapse to one named type that serves
 * both directions. {@link AspectCategory} (was `AgentCategoryInput` +
 * `AspectCategoryRef`) carries an optional `id` — compose ignores it
 * (server mints); pull populates it. {@link AspectNumericFieldFormat}
 * and {@link AspectFieldQrFormat} live in `format.ts` and likewise
 * serve both directions. {@link PicklistValue} (was
 * `AspectPicklistValue` + `PicklistValuePull`) is the canonical
 * picklist-value shape — read endpoints populate id+label only; pull
 * additionally populates active/color/icon/parentPicklistValueIds.
 * One field-result row type ({@link AspectFieldResult}) covers
 * compose-created, update-updated, and update-created results — the
 * shapes were structurally identical apart from the `system` flag.
 * One {@link AspectOperationSummary} covers both compose and update
 * summary slots with optional counters.
 */
export {};
